DO $historical$
DECLARE
  v_run uuid := gen_random_uuid();
  v_time timestamptz := clock_timestamp();
  r record; c public.mux_deletion_candidates%ROWTYPE; ref jsonb;
  v_missing integer := 0; v_survivors integer := 0;
  v_uploads_before text; v_other_before text; v_control_before jsonb; v_cron_before jsonb;
  v_guard_before text; v_previous_claim text;
  v_excluded text[] := ARRAY['VTO5q8FXmfTeeRkKTJY029xTn6OQScwgp01oN00ZyTV5K4','Q00EpNYlqK5OtvCsZhcqoa02onvTiNgD3Hu9LG4bE2Bro'];
  v_assets text[] := ARRAY[
'009F02wBkXGPdFyJBXKS6ICTQIGIFvQr6vfPKmCGBEKbg','01iP8GGiCMWdIV2HuDzjtPgecpgpzfd01YyboopTt3ulc','02AsA35Sn8Fw8NJ015HcXt02MP2LIWR4PimDewCbX6K4cc','17DfI0144ZrsUjrpaguD9vV0100EWZdLtIgU5gjDpA01QYA','1o1Xq4b3b1bzyi00PNLDnd5jgY02oyT02RN4SvcFXAoeJc','1vgGYOB6Jk3TZb01fvS02A1K3ojZiBhxuOb2PIM400v5Mg','2LbKK9QglpPMRy00CTALJMpBE01Ao3DXR6mJ2roWkOPwg','2epq1IJmfJZw32MCiVXUNECNfvYIFJMvrFmSJZrlVl00','3YBzWiPJD4J2iidwExd8NVAKF01Mf01CuEEjDkQADKQ5w','4V02FZav2wdbo2dv302mAMjcYWc2ICsX00cwkFsIffCFVE','4e01qUhCGuD01P2Xha01aiRn4uxoL026IXZiua01cBty8JzQ','67xPUi36FLxKyCVHl00X4tWqfNLBs2kAK017rDb1Lxt8M','6AZgR02T4AjuBHomz1Zehh3kx4m101602Q02w74dV5b7RW4','6IB01JPZzopVkGFIx5wO6t9aMQVgMJ22Y101FdoveYI3c','6MCMjRo02YyukGVM1aS2ndeuiK702di173B8Bpib3PUyw','6yxPz77iGFbGLOfWw8wwv7uK6pMDIzQ02H02vfar3DJJ4','7URpvIhKpgpNIz003TjhMmCzX402fA01PpetucYKx4nIm8','8oxqnYaB6ZrT01029NfXRSO1s01jkr1G00AB2Lm00KnNkdj00','9004TREvEZJuimXwbU1MfTApiUlpdtBa5p8hO2I9Hhis','977zNtCwzAhexDcv2l0102gga3EOH1ySOHFfEqKWuIdq8','AUGan0076NwRhvIJurCN02ZXmMvqMnVCZLCy1SqquyILg','DqfLYb2Q01E3qXKglfisoy6D3eGU3DiDgnrIl7shmX01g','E55ciIfvJdf1JZQwIyVgZRKL2UJWTkZarNVvgvEcSkE','ES9U2PIZ67LKPwoQxFxL1l00T2VpYQXZPOE5TrdCt9XQ','I5HQ7cBMiuIxS5yZgIuf00t1PBa5ObE4UpmzM3GjGhQU','JaRHJcEIHFWIYOKA5FQT9QYCV02LsJa1A4s901Mhwqcaw','JnawNWflCFQXK78jpQI5Sshxc02yHT32SRRwQ01HkV3us','K69IHKCAaWA1qW4014T8aVvHqvdE4CGQp2Z5dFSD00fsA','LT802Mh34BjIK00auxzjR23UxVYpdEry01cT3HkFX01bd1s','M6IQsE6kT3i7cGNperHXXCw01WU78q1kbj7tf7uoa44U','OhRVQZWt009KicYsfo6cArpvLmc6Oe01zYhDV8sAtUh5g','PAlSJJpCHrjrq7FhlYx3XLV5sVWCG7L6SOQ5V19LabE','POHyhUzghgqnc5hdcr7G02nJj2IsW00Lc1x02IdfNX9sA00','POObQ0077hmXvwjKaNgoJogCj900tsaxoEzVdsSyccqik','PWsOsUaaGBKVNoLVia3CkUN6ObQ01t6uFUOfmNwjUBbE','PoG02iOfX69R64AXy7eks93XDc8urEnfB01Jr5AIEY1Sk','QeQAmjmhD5gXBC4WWeR6tHpVT013PoiwZKTvDcUfDMk8','UkBVjFzhnVXgN3m7o00ttxXPUgUUdAt01wYG3iWVKt0284','Xw02c5LbTNy011jrH5pEid3VOA007kMDoyFYchSttmnM7M','a02KRHh51FTIHZrXJ5cBdzeIfUx2roOCF11C9qcIAT8o','aZ02X8YrU8DmuEYIeNhiAoY8TpZC6R7eYW01PXuTF9tPI','faSQVFdaeIa5BlvWZ4yWH