  v_present text[] := ARRAY['4e01qUhCGuD01P2Xha01aiRn4uxoL026IXZiua01cBty8JzQ','977zNtCwzAhexDcv2l0102gga3EOH1ySOHFfEqKWuIdq8','DqfLYb2Q01E3qXKglfisoy6D3eGU3DiDgnrIl7shmX01g','zgq02dHpBCG100JuFBHeXmlzPb39HnyxrOBi4IUO7UWTg'];
BEGIN
  PERFORM set_config('lock_timeout','5s',true);
  IF cardinality(v_assets) <> 72 OR v_assets && v_excluded THEN RAISE EXCEPTION 'Invalid historical allowlist'; END IF;
  IF (SELECT count(*) FROM public.mux_deletion_candidates WHERE mux_asset_id=ANY(v_assets) AND status='protected_ambiguous' AND protection_reason='age_only_no_abandonment_policy' AND source_kind='unlinked_sweep' AND created_at < '2026-10-20'::timestamptz AND NOT is_destructively_claimed) <> 72 THEN RAISE EXCEPTION 'Historical manifest/state mismatch; no changes applied'; END IF;
  SELECT md5(COALESCE(jsonb_agg(to_jsonb(u) ORDER BY id)::text,'')) INTO v_uploads_before FROM public.mux_uploads u;
  SELECT md5(COALESCE(jsonb_agg(to_jsonb(c0) ORDER BY id)::text,'')) INTO v_other_before FROM public.mux_deletion_candidates c0 WHERE NOT mux_asset_id=ANY(v_assets);
  SELECT jsonb_agg(to_jsonb(t)) INTO v_control_before FROM public.mux_cleanup_live_control t;
  SELECT jsonb_agg(jsonb_build_object('jobid',jobid,'schedule',schedule,'active',active)) INTO v_cron_before FROM cron.job WHERE jobname='mux-cleanup-live-hourly';
  SELECT pg_get_functiondef('public.mux_candidates_guard()'::regprocedure) INTO v_guard_before;
  -- Only add a truthful audit label; no candidate-status or protection rules change.
  ALTER TABLE public.mux_cleanup_audit_logs DROP CONSTRAINT mux_cleanup_audit_logs_action_check;
  ALTER TABLE public.mux_cleanup_audit_logs ADD CONSTRAINT mux_cleanup_audit_logs_action_check CHECK (action IN ('promoted_eligible','rescued_referenced','kept_protected','simulated_would_delete','skipped_referenced','skipped_ambiguous','skipped_destructive','deleted_live','reconciled_404','errored','claimed_live','retry_scheduled','failed_manual','historical_requeued'));
  -- Preserve established upload -> asset -> candidate lock order.
  PERFORM 1 FROM public.mux_uploads WHERE asset_id=ANY(v_assets) ORDER BY id FOR UPDATE;
  PERFORM public.mux_lock_assets(v_assets);
  FOR r IN SELECT mux_asset_id FROM public.mux_deletion_candidates WHERE mux_asset_id=ANY(v_assets) ORDER BY mux_asset_id LOOP
    SELECT * INTO c FROM public.mux_deletion_candidates WHERE mux_asset_id=r.mux_asset_id FOR UPDATE;
    IF c.status <> 'protected_ambiguous' OR c.is_destructively_claimed OR c.worker_lease_id IS NOT NULL THEN RAISE EXCEPTION 'Historical state changed for %; full rollback',c.mux_asset_id; END IF;
    ref := public.mux_asset_reference_state(c.mux_asset_id);
    IF ref->>'state' IS DISTINCT FROM 'unreferenced' THEN RAISE EXCEPTION 'Reference safety check failed for %: %; full rollback',c.mux_asset_id,ref; END IF;
    IF EXISTS (SELECT 1 FROM public.entities e JOIN public.mux_uploads u ON u.asset_id=c.mux_asset_id WHERE strpos(COALESCE(e.image_url,'')||COALESCE(e.description,''),c.mux_asset_id)>0 OR (u.playback_id IS NOT NULL AND strpos(COALESCE(e.image_url,'')||COALESCE(e.description,''),u.playback_id)>0)) THEN RAISE EXCEPTION 'Entity dependency for %; full rollback',c.mux_asset_id; END IF;
    IF EXISTS (SELECT 1 FROM public.profiles p JOIN public.mux_uploads u ON u.asset_id=c.mux_asset_id WHERE strpos(COALESCE(p.avatar_url,'')||COALESCE(p.bio,''),c.mux_asset_id)>0 OR (u.playback_id IS NOT NULL AND strpos(COALESCE(p.avatar_url,'')||COALESCE(p.bio,''),u.playback_id)>0)) THEN RAISE EXCEPTION 'Profile dependency for %; full rollback',c.mux_asset_id; END IF;
    IF c.mux_asset_id=ANY(v_present) THEN
      UPDATE public.mux_deletion_candidates SET status='pending_grace', protection_reason=NULL, discovered_at=v_time, eligible_at=v_time+interval '24 hours', lifecycle_attempt=lifecycle_attempt+1, last_checked_at=v_time,last_check_result='unreferenced',error_details=jsonb_build_object('reason','operator_authorized_dummy_historical_cleanup','run_id',v_run) WHERE id=c.id;
      INSERT INTO public.mux_cleanup_audit_logs(run_id,mode,candidate_id,mux_asset_id,action,details) VALUES(v_run,'live',c.id,c.mux_asset_id,'historical_requeued',jsonb_build_object('reason','operator_authorized_dummy_historical_cleanup','from_status',c.status,'to_status','pending_grace','previous_discovered_at',c.discovered_at,'previous_eligible_at',c.eligible_at,'discovered_at',v_time,'eligible_at',v_time+interval '24 hours','reference',ref,'mux_get_http_status',200,'mux_existence_verified_at','2026-10-25T08:17:37Z','mux_delete_issued',false));
      v_survivors:=v_survivors+1;
    ELSE
      -- Existing guard authorization, scoped to this administrative transaction.
      -- The permanent barrier records known remote absence, NOT a worker DELETE.
      v_previous_claim := COALESCE(current_setting('mux.live_claim',true),'off');
      PERFORM set_config('mux.live_claim','on',true);
      UPDATE public.mux_deletion_candidates SET status='reconciled_already_deleted',is_destructively_claimed=true,destructive_claim_token=gen_random_uuid(),destructive_claimed_at=v_time,claim_generation=claim_generation+1,protection_reason=NULL,last_checked_at=v_time,last_check_result='externally_missing_from_mux',error_details=jsonb_build_object('reason','externally_missing_from_mux','operation','operator_historical_reconciliation','run_id',v_run,'mux_delete_issued',false) WHERE id=c.id;
      PERFORM set_config('mux.live_claim',v_previous_claim,true);
      INSERT INTO public.mux_cleanup_audit_logs(run_id,mode,candidate_id,mux_asset_id,action,details) VALUES(v_run,'live',c.id,c.mux_asset_id,'reconciled_404',jsonb_build_object('reason','externally_missing_from_mux','operation','operator_historical_reconciliation','from_status',c.status,'to_status','reconciled_already_deleted','reference',ref,'http_status',404,'http_method','GET','mux_existence_verified_at','2026-10-25T08:17:37Z','mux_delete_issued',false,'barrier_purpose','prevent_attachment_to_known_missing_asset','deletion_time_and_cause','unknown'));
      v_missing:=v_missing+1;
    END IF;
  END LOOP;
  IF v_missing<>68 OR v_survivors<>4 THEN RAISE EXCEPTION 'Wrong result totals; full rollback'; END IF;
  IF (SELECT count(*) FROM public.mux_cleanup_audit_logs WHERE run_id=v_run)<>72 THEN RAISE EXCEPTION 'Wrong audit count; full rollback'; END IF;
  IF EXISTS (SELECT 1 FROM public.mux_deletion_candidates WHERE mux_asset_id=ANY(v_present) AND (status<>'pending_grace' OR eligible_at<>v_time+interval '24 hours' OR discovered_at<>v_time OR is_destructively_claimed)) THEN RAISE EXCEPTION 'Fresh 24h grace check failed'; END IF;
  IF (SELECT md5(COALESCE(jsonb_agg(to_jsonb(u) ORDER BY id)::text,'')) FROM public.mux_uploads u) IS DISTINCT FROM v_uploads_before THEN RAISE EXCEPTION 'Upload history changed; full rollback'; END IF;
  IF (SELECT md5(COALESCE(jsonb_agg(to_jsonb(c0) ORDER BY id)::text,'')) FROM public.mux_deletion_candidates c0 WHERE NOT mux_asset_id=ANY(v_assets)) IS DISTINCT FROM v_other_before THEN RAISE EXCEPTION 'Nonhistorical/excluded candidate changed; full rollback'; END IF;
  IF (SELECT jsonb_agg(to_jsonb(t)) FROM public.mux_cleanup_live_control t) IS DISTINCT FROM v_control_before OR (SELECT jsonb_agg(jsonb_build_object('jobid',jobid,'schedule',schedule,'active',active)) FROM cron.job WHERE jobname='mux-cleanup-live-hourly') IS DISTINCT FROM v_cron_before OR pg_get_functiondef('public.mux_candidates_guard()'::regprocedure) IS DISTINCT FROM v_guard_before THEN RAISE EXCEPTION 'Control/cron/guard changed; full rollback'; END IF;
  RAISE NOTICE 'Historical reconciliation run %: 68 externally missing reconciled, 4 fresh pending grace at %, 72 audits, exclusions/uploads/cron/control/guard unchanged',v_run,v_time;
END $historical$;